// Package validator is the driver-independent store validator of decision
// D34 (dev-docs/design-record.md §4.1, §4.3 item 4): every write is checked
// against the kudurru CRDs exactly as the Kubernetes apiserver checks it,
// before any store driver sees it, so the sqlite driver (Docker) and the
// kube driver (Kubernetes) reject the same inputs.
//
// The CRD manifests generated by `make manifests` are embedded (see
// crds.go). For each kind the validator builds what the apiserver builds
// when it serves a CRD: the structural schema, the OpenAPI schema validator
// (with validation ratcheting on updates), and the compiled
// x-kubernetes-validations CEL programs, all from
// k8s.io/apiextensions-apiserver. A write then goes through the same steps
// as a create or update request through the apiserver:
//
//  1. decode: prune unknown fields, drop non-nullable nulls, coerce
//     metadata, apply schema defaults;
//  2. prepare: on create the status is ignored, on update the old status is
//     kept (all kudurru kinds have a status subresource); identity fields
//     (uid, creationTimestamp, generation) are taken from the old object;
//  3. validate: object metadata (name is a DNS subdomain, namespace present
//     only for namespaced kinds, labels and annotations), the OpenAPI schema
//     (types, enums, patterns, required, bounds), embedded resources,
//     list-type map/set uniqueness, then the CEL rules including transition
//     rules that reference oldSelf.
//
// Cross-object checks (a record set outside its zone, duplicates across
// namespaces) are not validation; reconcilers report them as conditions.
//
// The sequence mirrors customResourceStrategy in
// k8s.io/apiextensions-apiserver/pkg/registry/customresource (Apache-2.0),
// which cannot be imported without the apiserver storage stack.
package validator

import (
	"context"
	"encoding/json"
	"fmt"
	"reflect"
	"sort"

	structuralschema "k8s.io/apiextensions-apiserver/pkg/apiserver/schema"
	"k8s.io/apiextensions-apiserver/pkg/apiserver/schema/cel"
	"k8s.io/apiextensions-apiserver/pkg/apiserver/schema/cel/model"
	structuraldefaulting "k8s.io/apiextensions-apiserver/pkg/apiserver/schema/defaulting"
	structurallisttype "k8s.io/apiextensions-apiserver/pkg/apiserver/schema/listtype"
	schemaobjectmeta "k8s.io/apiextensions-apiserver/pkg/apiserver/schema/objectmeta"
	structuralpruning "k8s.io/apiextensions-apiserver/pkg/apiserver/schema/pruning"
	apiservervalidation "k8s.io/apiextensions-apiserver/pkg/apiserver/validation"
	"k8s.io/apimachinery/pkg/api/operation"
	metavalidation "k8s.io/apimachinery/pkg/api/validation"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/runtime/schema"
	utiljson "k8s.io/apimachinery/pkg/util/json"
	"k8s.io/apimachinery/pkg/util/validation/field"
	celconfig "k8s.io/apiserver/pkg/apis/cel"
	"k8s.io/apiserver/pkg/cel/common"
	"k8s.io/apiserver/pkg/features"
	utilfeature "k8s.io/apiserver/pkg/util/feature"

	"github.com/robertherbaugh/kudurru/internal/store"
)

// Validator validates kudurru objects against the embedded CRDs. It is safe
// for concurrent use; build one per process with New and share it.
type Validator struct {
	kinds map[store.Kind]*kindSchema
}

// New builds a Validator from the CRDs compiled into the binary.
func New() (*Validator, error) {
	files, err := EmbeddedCRDs()
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(files))
	for n := range files {
		names = append(names, n)
	}
	sort.Strings(names)
	docs := make([][]byte, 0, len(names))
	for _, n := range names {
		docs = append(docs, files[n])
	}
	return NewFromCRDs(docs...)
}

// NewFromCRDs builds a Validator from CustomResourceDefinition manifests
// (one document each). Tests and future kinds use it; production uses New.
func NewFromCRDs(docs ...[]byte) (*Validator, error) {
	v := &Validator{kinds: make(map[store.Kind]*kindSchema, len(docs))}
	for i, doc := range docs {
		ks, err := parseCRD(doc)
		if err != nil {
			return nil, fmt.Errorf("validator: CRD #%d: %w", i, err)
		}
		k := store.Kind(ks.gvk.Kind)
		if _, dup := v.kinds[k]; dup {
			return nil, fmt.Errorf("validator: kind %s defined twice", k)
		}
		v.kinds[k] = ks
	}
	return v, nil
}

// Kinds lists the kinds the validator knows, sorted.
func (v *Validator) Kinds() []store.Kind {
	out := make([]store.Kind, 0, len(v.kinds))
	for k := range v.kinds {
		out = append(out, k)
	}
	sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
	return out
}

// GroupVersionKind returns the served group/version/kind and whether the
// kind is namespaced.
func (v *Validator) GroupVersionKind(kind store.Kind) (gvk schema.GroupVersionKind, namespaced bool, ok bool) {
	ks, ok := v.kinds[kind]
	if !ok {
		return schema.GroupVersionKind{}, false, false
	}
	return ks.gvk, ks.namespaced, true
}

// HasStatusSubresource reports whether the registered CRD serves /status.
// Complete-image validation uses this to validate status only where the main
// resource validator deliberately leaves it to a separate admission path.
func (v *Validator) HasStatusSubresource(kind store.Kind) bool {
	ks, ok := v.kinds[kind]
	return ok && ks.hasStatus
}

// Validate checks a write of obj, the whole object a caller passes to
// store.Store.Apply. old is the currently stored object, or nil on create;
// with old set, transition rules (CEL oldSelf, immutability) and validation
// ratcheting apply exactly as on an apiserver update.
//
// Like the apiserver, Validate applies the schema defaults: on success obj
// is replaced by its defaulted form (for example DNSZone spec.defaultTTL
// 300 and the SOA timers), which is what every driver persists. On failure
// obj is unchanged and the error is a *Error carrying one Cause per field.
//
// The status of obj is not validated here: the main resource cannot change
// status when a status subresource exists (creates ignore it, updates keep
// the old one). Status writes go through ValidateStatus.
//
// Typed objects reach the validator through their JSON encoding, the same
// bytes a Kubernetes client sends. Fields that encoding cannot leave out
// (non-pointer structs such as metav1.Duration with omitempty, and fields
// without omitempty) therefore arrive as zero values and are not
// defaulted, in both modes; use ValidateUnstructured for decoded input.
func (v *Validator) Validate(ctx context.Context, obj, old store.Object) error {
	ks, err := v.kindFor(obj, old)
	if err != nil {
		return err
	}
	u, err := toUnstructured(obj, ks.gvk)
	if err != nil {
		return err
	}
	var ou map[string]any
	if !isNil(old) {
		if ou, err = toUnstructured(old, ks.gvk); err != nil {
			return err
		}
	}
	if err := v.admit(ctx, ks, u, ou, false); err != nil {
		return err
	}
	return fromUnstructured(u, obj)
}

// ValidateStatus checks a status write of obj (store.Store.UpdateStatus)
// against the stored object old, like a PUT to the /status subresource:
// metadata and spec are taken from old, the status of obj is validated
// against the status schema with ratcheting, and the CEL rules run on the
// merged object. On success the status of obj is replaced by its defaulted
// form.
func (v *Validator) ValidateStatus(ctx context.Context, obj, old store.Object) error {
	if isNil(old) {
		return fmt.Errorf("validator: ValidateStatus needs the stored object")
	}
	ks, err := v.kindFor(obj, old)
	if err != nil {
		return err
	}
	if !ks.hasStatus {
		return fmt.Errorf("validator: %s has no status subresource", ks.gvk.Kind)
	}
	u, err := toUnstructured(obj, ks.gvk)
	if err != nil {
		return err
	}
	ou, err := toUnstructured(old, ks.gvk)
	if err != nil {
		return err
	}
	if errs := normalize(ks, u, nil); len(errs) > 0 {
		return newError(ks.gvk.GroupKind(), metaString(u, "namespace"), metaString(u, "name"), errs)
	}
	if errs := normalize(ks, ou, nil); len(errs) > 0 {
		return fmt.Errorf("validator: stored %s is malformed: %w", ks.gvk.Kind, errs.ToAggregate())
	}

	// statusStrategy.PrepareForUpdate: everything but status comes from old.
	merged := runtime.DeepCopyJSON(ou)
	if st, ok := u["status"]; ok {
		merged["status"] = runtime.DeepCopyJSONValue(st)
	} else {
		delete(merged, "status")
	}
	ensureResourceVersion(merged, ou)

	errs := validateStatusUpdate(ctx, ks, merged, ou)
	if len(errs) > 0 {
		return newError(ks.gvk.GroupKind(), metaString(merged, "namespace"), metaString(merged, "name"), errs)
	}
	return setStatus(obj, merged)
}

// PruneApplyNulls removes non-nullable, defaultless null fields from a private
// SSA payload, matching the decode normalization used by Validate. Kubernetes
// SSA type-checks its apply configuration before normal CRD decode pruning; a
// typed nil slice would otherwise report TypeInvalid/null instead of Required.
// Nullable values, list elements, schema defaults and validation remain the
// destination's responsibility. The caller must pass its own payload copy.
func (v *Validator) PruneApplyNulls(obj *unstructured.Unstructured) error {
	if obj == nil {
		return fmt.Errorf("validator: nil object")
	}
	ks, ok := v.kinds[store.Kind(obj.GetKind())]
	if !ok || obj.GroupVersionKind() != ks.gvk {
		return fmt.Errorf("%w: %s", ErrUnknownKind, obj.GroupVersionKind())
	}
	structuraldefaulting.PruneNonNullableNullsWithoutDefaults(obj.Object, ks.structural)
	return nil
}

// ValidateUnstructured is Validate for decoded YAML or JSON (the API, `kudurru
// apply -f`, objects.d files) before it is converted to a Go type. Unlike
// the typed path it can see fields the schema does not declare and rejects
// them, like kubectl's default --validate=strict, and it can tell an absent
// field from a zero one, so every schema default applies. apiVersion and
// kind must name a kudurru kind. On success obj holds the defaulted object.
func (v *Validator) ValidateUnstructured(ctx context.Context, obj, old *unstructured.Unstructured) error {
	if obj == nil {
		return fmt.Errorf("validator: nil object")
	}
	gvk := obj.GroupVersionKind()
	ks, ok := v.kinds[store.Kind(gvk.Kind)]
	if !ok || gvk.Group != ks.gvk.Group {
		return fmt.Errorf("%w: %s", ErrUnknownKind, gvk.String())
	}
	if errs := validateTypeMeta(obj.Object, ks.gvk); len(errs) > 0 {
		return newError(ks.gvk.GroupKind(), obj.GetNamespace(), obj.GetName(), errs)
	}
	u := runtime.DeepCopyJSON(obj.Object)
	var ou map[string]any
	if old != nil {
		ou = runtime.DeepCopyJSON(old.Object)
		ou["apiVersion"], ou["kind"] = ks.gvk.GroupVersion().String(), ks.gvk.Kind
	}
	if err := v.admit(ctx, ks, u, ou, true); err != nil {
		return err
	}
	obj.Object = u
	return nil
}

// admit runs decode, prepare and validate on u (defaulted in place). ou is
// the stored object for updates, nil for creates.
func (v *Validator) admit(ctx context.Context, ks *kindSchema, u, ou map[string]any, strict bool) error {
	gk := ks.gvk.GroupKind()
	var unknown []string
	if errs := normalize(ks, u, &unknown); len(errs) > 0 {
		return newError(gk, metaString(u, "namespace"), metaString(u, "name"), errs)
	}
	if strict && len(unknown) > 0 {
		return newUnknownFieldsError(gk, metaString(u, "namespace"), metaString(u, "name"), unknown)
	}

	var errs field.ErrorList
	if ou == nil {
		errs = validateCreate(ctx, ks, prepareCreate(ks, u))
	} else {
		if oerrs := normalize(ks, ou, nil); len(oerrs) > 0 {
			return fmt.Errorf("validator: stored %s is malformed: %w", ks.gvk.Kind, oerrs.ToAggregate())
		}
		errs = validateUpdate(ctx, ks, prepareUpdate(ks, u, ou), ou)
	}
	if len(errs) > 0 {
		return newError(gk, metaString(u, "namespace"), metaString(u, "name"), errs)
	}
	return nil
}

// normalize is the apiserver's decode path for a custom resource
// (unstructuredSchemaCoercer.apply followed by unstructuredDefaulter):
// prune fields the schema does not declare, drop nulls of non-nullable
// fields without a default, coerce metadata, then apply defaults. Pruned
// paths are appended to unknown when it is non-nil.
func normalize(ks *kindSchema, u map[string]any, unknown *[]string) field.ErrorList {
	kind, apiVersion := u["kind"], u["apiVersion"]
	objectMeta, foundMeta, metaUnknown, err := schemaobjectmeta.GetObjectMetaWithOptions(u, schemaobjectmeta.ObjectMetaOptions{ReturnUnknownFieldPaths: unknown != nil})
	if err != nil {
		return field.ErrorList{field.Invalid(field.NewPath("metadata"), nil, err.Error())}
	}
	opts := structuralschema.UnknownFieldPathOptions{TrackUnknownFieldPaths: unknown != nil}
	pruned := structuralpruning.PruneWithOptions(u, ks.structural, true, opts)
	structuraldefaulting.PruneNonNullableNullsWithoutDefaults(u, ks.structural)
	ferr, coerced := schemaobjectmeta.CoerceWithOptions(nil, u, ks.structural, false, schemaobjectmeta.CoerceOptions{ReturnUnknownFieldPaths: unknown != nil})
	if ferr != nil {
		return field.ErrorList{ferr}
	}
	if kind != nil {
		u["kind"] = kind
	}
	if apiVersion != nil {
		u["apiVersion"] = apiVersion
	}
	if foundMeta {
		if err := schemaobjectmeta.SetObjectMeta(u, objectMeta); err != nil {
			return field.ErrorList{field.Invalid(field.NewPath("metadata"), nil, err.Error())}
		}
	}
	structuraldefaulting.Default(u, ks.structural)
	if unknown != nil {
		*unknown = append(*unknown, metaUnknown...)
		*unknown = append(*unknown, pruned...)
		*unknown = append(*unknown, coerced...)
	}
	return nil
}

// prepareCreate returns the object the apiserver validates on create
// (rest.BeforeCreate + customResourceStrategy.PrepareForCreate): status is
// dropped when the status subresource exists and deletion fields are
// cleared. u itself is not modified.
func prepareCreate(ks *kindSchema, u map[string]any) map[string]any {
	view := shallowCopy(u)
	if ks.hasStatus {
		delete(view, "status")
	}
	if m, ok := view["metadata"].(map[string]any); ok {
		m = shallowCopy(m)
		delete(m, "deletionTimestamp")
		delete(m, "deletionGracePeriodSeconds")
		view["metadata"] = m
	}
	return view
}

// prepareUpdate returns the object the apiserver validates on update
// (rest.BeforeUpdate + customResourceStrategy.PrepareForUpdate): the old
// status is kept when the status subresource exists, and the identity
// fields the server owns come from the stored object. resourceVersion is a
// concurrency token the drivers check (store.ErrConflict); the view always
// carries one so metadata validation does not report it.
func prepareUpdate(ks *kindSchema, u, ou map[string]any) map[string]any {
	view := shallowCopy(u)
	if ks.hasStatus {
		if st, ok := ou["status"]; ok {
			view["status"] = st
		} else {
			delete(view, "status")
		}
	}
	m, _ := view["metadata"].(map[string]any)
	m = shallowCopy(m)
	om, _ := ou["metadata"].(map[string]any)
	for _, k := range []string{"generation", "creationTimestamp", "deletionTimestamp", "deletionGracePeriodSeconds"} {
		if val, ok := om[k]; ok {
			m[k] = val
		} else {
			delete(m, k)
		}
	}
	if s, _ := m["uid"].(string); s == "" {
		if val, ok := om["uid"]; ok {
			m["uid"] = val
		}
	}
	view["metadata"] = m
	ensureResourceVersion(view, ou)
	return view
}

// ensureResourceVersion gives view a resourceVersion when it has none.
func ensureResourceVersion(view, ou map[string]any) {
	m, ok := view["metadata"].(map[string]any)
	if !ok {
		m = map[string]any{}
	}
	m = shallowCopy(m)
	if s, _ := m["resourceVersion"].(string); s == "" {
		rv := metaString(ou, "resourceVersion")
		if rv == "" {
			rv = "0"
		}
		m["resourceVersion"] = rv
	}
	view["metadata"] = m
}

// validateCreate is customResourceStrategy.Validate.
func validateCreate(ctx context.Context, ks *kindSchema, u map[string]any) field.ErrorList {
	var errs field.ErrorList
	meta, merrs := objectMetaOf(u)
	if len(merrs) > 0 {
		errs = append(errs, merrs...)
	} else {
		errs = append(errs, metavalidation.ValidateObjectMetaDeclaratively(ctx, operation.Create, meta, nil, ks.namespaced, metavalidation.NameIsDNSSubdomain, field.NewPath("metadata"), declarativeBeta())...)
	}
	errs = append(errs, apiservervalidation.ValidateCustomResource(nil, u, ks.schemaValidator)...)
	errs = append(errs, schemaobjectmeta.Validate(ctx, nil, u, ks.structural, false)...)
	errs = append(errs, structurallisttype.ValidateListSetsAndMaps(nil, ks.structural, u)...)
	if ks.cel != nil {
		if blocking := blockingError(errs); blocking != nil {
			errs = append(errs, blocking)
		} else {
			cerrs, _ := ks.cel.Validate(ctx, nil, ks.structural, u, nil, celconfig.RuntimeCELCostBudget)
			errs = append(errs, cerrs...)
		}
	}
	return errs
}

// validateUpdate is customResourceStrategy.ValidateUpdate with validation
// ratcheting (CRDValidationRatcheting is GA and locked on since 1.33).
func validateUpdate(ctx context.Context, ks *kindSchema, u, ou map[string]any) field.ErrorList {
	correlated := common.NewCorrelatedObject(u, ou, &model.Structural{Structural: ks.structural})
	var errs field.ErrorList
	meta, merrs := objectMetaOf(u)
	oldMeta, omerrs := objectMetaOf(ou)
	switch {
	case len(merrs) > 0:
		errs = append(errs, merrs...)
	case len(omerrs) > 0:
		errs = append(errs, omerrs...)
	default:
		errs = append(errs, metavalidation.ValidateObjectMetaDeclaratively(ctx, operation.Update, meta, oldMeta, ks.namespaced, nil, field.NewPath("metadata"), declarativeBeta())...)
	}
	errs = append(errs, apiservervalidation.ValidateCustomResourceUpdate(nil, u, ou, ks.schemaValidator, apiservervalidation.WithRatcheting(correlated))...)
	errs = append(errs, schemaobjectmeta.Validate(ctx, nil, u, ks.structural, false)...)
	if oldErrs := structurallisttype.ValidateListSetsAndMaps(nil, ks.structural, ou); len(oldErrs) == 0 {
		errs = append(errs, structurallisttype.ValidateListSetsAndMaps(nil, ks.structural, u)...)
	}
	if ks.cel != nil {
		if blocking := blockingError(errs); blocking != nil {
			errs = append(errs, blocking)
		} else {
			cerrs, _ := ks.cel.Validate(ctx, nil, ks.structural, u, ou, celconfig.RuntimeCELCostBudget, cel.WithRatcheting(correlated))
			errs = append(errs, cerrs...)
		}
	}
	return errs
}

// validateStatusUpdate is statusStrategy.ValidateUpdate.
func validateStatusUpdate(ctx context.Context, ks *kindSchema, u, ou map[string]any) field.ErrorList {
	correlated := common.NewCorrelatedObject(u, ou, &model.Structural{Structural: ks.structural})
	var errs field.ErrorList
	meta, merrs := objectMetaOf(u)
	oldMeta, omerrs := objectMetaOf(ou)
	switch {
	case len(merrs) > 0:
		errs = append(errs, merrs...)
	case len(omerrs) > 0:
		errs = append(errs, omerrs...)
	default:
		errs = append(errs, metavalidation.ValidateObjectMetaDeclaratively(ctx, operation.Update, meta, oldMeta, ks.namespaced, nil, field.NewPath("metadata"), declarativeBeta())...)
	}
	if st, ok := u["status"]; ok && ks.statusValidator != nil {
		errs = append(errs, apiservervalidation.ValidateCustomResourceUpdate(field.NewPath("status"), st, ou["status"], ks.statusValidator, apiservervalidation.WithRatcheting(correlated.Key("status")))...)
	}
	if newErrs := structurallisttype.ValidateListSetsAndMaps(nil, ks.structural, u); len(newErrs) > 0 {
		if oldErrs := structurallisttype.ValidateListSetsAndMaps(nil, ks.structural, ou); len(oldErrs) == 0 {
			errs = append(errs, newErrs...)
		}
	}
	if ks.cel != nil {
		if blocking := blockingError(errs); blocking != nil {
			errs = append(errs, blocking)
		} else {
			cerrs, _ := ks.cel.Validate(ctx, nil, ks.structural, u, ou, celconfig.RuntimeCELCostBudget, cel.WithRatcheting(correlated))
			errs = append(errs, cerrs...)
		}
	}
	return errs
}

// blockingError mirrors hasBlockingErr in the apiserver: OpenAPI failures
// of these types mean the CEL rules are not evaluated, because their inputs
// cannot be trusted.
func blockingError(errs field.ErrorList) *field.Error {
	for _, err := range errs {
		switch err.Type {
		case field.ErrorTypeNotSupported, field.ErrorTypeRequired, field.ErrorTypeTooLong, field.ErrorTypeTooMany, field.ErrorTypeTypeInvalid:
			return field.Invalid(nil, nil, "some validation rules were not checked because the object was invalid; correct the existing errors to complete validation")
		}
	}
	return nil
}

func validateTypeMeta(u map[string]any, gvk schema.GroupVersionKind) field.ErrorList {
	var errs field.ErrorList
	if k, _ := u["kind"].(string); k != gvk.Kind {
		errs = append(errs, field.Invalid(field.NewPath("kind"), k, "must be "+gvk.Kind))
	}
	if av, _ := u["apiVersion"].(string); av != gvk.GroupVersion().String() {
		errs = append(errs, field.Invalid(field.NewPath("apiVersion"), av, "must be "+gvk.GroupVersion().String()))
	}
	return errs
}

func declarativeBeta() bool {
	return utilfeature.DefaultFeatureGate.Enabled(features.DeclarativeValidationBeta)
}

func (v *Validator) kindFor(obj, old store.Object) (*kindSchema, error) {
	if isNil(obj) {
		return nil, fmt.Errorf("validator: nil object")
	}
	kind := store.KindOf(obj)
	ks, ok := v.kinds[kind]
	if !ok {
		return nil, fmt.Errorf("%w: %s", ErrUnknownKind, kind)
	}
	if !isNil(old) && store.KindOf(old) != kind {
		return nil, fmt.Errorf("validator: old object is a %s, new object is a %s", store.KindOf(old), kind)
	}
	return ks, nil
}

// toUnstructured encodes a typed object the way a Kubernetes client puts it
// on the wire (encoding/json) and decodes it the way the apiserver does
// (integers as int64). apiVersion and kind come from the CRD, as a client
// sets them from its scheme.
func toUnstructured(obj store.Object, gvk schema.GroupVersionKind) (map[string]any, error) {
	b, err := json.Marshal(obj)
	if err != nil {
		return nil, fmt.Errorf("validator: encode %s: %w", gvk.Kind, err)
	}
	u := map[string]any{}
	if err := utiljson.Unmarshal(b, &u); err != nil {
		return nil, fmt.Errorf("validator: decode %s: %w", gvk.Kind, err)
	}
	u["apiVersion"], u["kind"] = gvk.GroupVersion().String(), gvk.Kind
	return u, nil
}

// fromUnstructured replaces *into with the decoded u.
func fromUnstructured(u map[string]any, into store.Object) error {
	fresh, err := decodeTyped(u, into)
	if err != nil {
		return err
	}
	reflect.ValueOf(into).Elem().Set(reflect.ValueOf(fresh).Elem())
	return nil
}

// setStatus replaces the Status field of into with the one decoded from u.
func setStatus(into store.Object, u map[string]any) error {
	fresh, err := decodeTyped(u, into)
	if err != nil {
		return err
	}
	dst := reflect.ValueOf(into).Elem().FieldByName("Status")
	src := reflect.ValueOf(fresh).Elem().FieldByName("Status")
	if !dst.IsValid() || !dst.CanSet() {
		return fmt.Errorf("validator: %T has no Status field", into)
	}
	dst.Set(src)
	return nil
}

func decodeTyped(u map[string]any, like store.Object) (any, error) {
	b, err := json.Marshal(u)
	if err != nil {
		return nil, fmt.Errorf("validator: encode defaulted object: %w", err)
	}
	fresh := reflect.New(reflect.TypeOf(like).Elem()).Interface()
	if err := json.Unmarshal(b, fresh); err != nil {
		return nil, fmt.Errorf("validator: decode defaulted object: %w", err)
	}
	return fresh, nil
}

func objectMetaOf(u map[string]any) (*metav1.ObjectMeta, field.ErrorList) {
	raw, ok := u["metadata"]
	if !ok || raw == nil {
		return &metav1.ObjectMeta{}, nil
	}
	m, ok := raw.(map[string]any)
	if !ok {
		return nil, field.ErrorList{field.Invalid(field.NewPath("metadata"), raw, fmt.Sprintf("expected map[string]interface{}, got %T", raw))}
	}
	meta := &metav1.ObjectMeta{}
	if err := runtime.DefaultUnstructuredConverter.FromUnstructured(m, meta); err != nil {
		return nil, field.ErrorList{field.Invalid(field.NewPath("metadata"), raw, err.Error())}
	}
	return meta, nil
}

func metaString(u map[string]any, key string) string {
	m, _ := u["metadata"].(map[string]any)
	s, _ := m[key].(string)
	return s
}

func shallowCopy(m map[string]any) map[string]any {
	out := make(map[string]any, len(m)+1)
	for k, v := range m {
		out[k] = v
	}
	return out
}

// isNil reports whether o is nil or a typed nil pointer.
func isNil(o store.Object) bool {
	if o == nil {
		return true
	}
	rv := reflect.ValueOf(o)
	return rv.Kind() == reflect.Pointer && rv.IsNil()
}
